-- Passage rg4-text-structure-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('cf91c39f-918d-541e-bbde-28bcdad9b650', 'rg4-text-structure-p07', (select id from public.skills where slug = 'read-g4-text-structure'), null,
        '3-5', $q$How a Guitar String Makes Music$q$, $q$When you pluck a guitar string, it moves back and forth very fast. This movement is called vibration. The vibration shakes the air around it, and that is what you hear as sound.

Not every string sounds the same, though. The thickness of a string changes its sound. A thick string vibrates slowly, so it makes a low sound. A thin string vibrates quickly. As a result, it makes a high sound.

A player can also change the sound by pressing on a string. Pressing a finger down makes the part of the string that moves shorter. A shorter string vibrates faster, which causes a higher note.

Tightness matters too. When a player turns a knob to tighten a string, the note goes up. If the string gets loose, the note goes down. That is why players check their strings before every show.$q$, 'draft')
