-- Passage rg4-text-structure-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('6dc11841-ec5a-5617-a1cc-f7b0cc6415be', 'rg4-text-structure-p08', (select id from public.skills where slug = 'read-g4-text-structure'), null,
        '3-5', $q$The Lost-and-Found Mountain$q$, $q$At Riverside Elementary, the lost-and-found bin was overflowing. Jackets, water bottles, and lunch boxes were piled so high that they spilled onto the floor. Hardly anyone came to look for their things. At the end of each month, the pile only grew bigger.

The student council wanted to fix this problem. The members started by thinking about why it was happening. Most items had no names on them, and many students did not know where the bin was.

The council tried three ideas. First, they set up a table by the front door every Friday afternoon. Families could look through the items as they picked up their children. Second, they asked teachers to remind students to write their names on their belongings. Third, they took photos of the items and shared them in the school newsletter.

The ideas worked. In two months, most of the items went back to their owners. The council gave the rest to a clothing drive, so nothing went to waste.$q$, 'draft')
